interface Visitor                                          // degenerate base
interface CircleVisitor : Visitor { fun visit(circle: Circle) }

class Circle(private val r: Double) : Shape() {
    override fun accept(visitor: Visitor) {
        if (visitor is CircleVisitor) visitor.visit(this)   // smart cast, no explicit as
        else logger.debug("visitor cannot visit Circle")
    }
}
